; cart.asm -- appendix G: a cartridge for the console sessions
; generated by genG.py
        INCLUDE "msx.inc"
        OUTPUT "cart.rom"
        ORG $4000
        CART_HEADER init
init:   di
        VDP_REG 7, LIGHT_GREEN  ; the border
        VRAM_WRITE $1800
        ld a, $47
        out (VDP_DATA), a       ; a G at the top left of the page
        call sub
back:   nop
stop:   jr stop

sub:    ld b, 3
sloop:  djnz sloop
        ret
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
